+	if !isGeometryPlanType(&col.Typ) {
+		return moerr.NewNotSupported(ctx.GetContext(), fmt.Sprintf("SPATIAL INDEX can only be created on GEOMETRY column '%s'", nameOrigin))
+	}
+	return nil
