+func appendUniqueGeometryPoints(points []geometryPoint2D, point geometryPoint2D) []geometryPoint2D {
+	for _, existing := range points {
+		if sameGeometryPoint(existing, point) {
+			return points
+		}
+	}
+	return append(points, point)
+}
