+	if !pointInPolygon(polygon.outer, point.x, point.y) {
+		return false
+	}
+	for _, hole := range polygon.holes {
+		if pointInPolygon(hole, point.x, point.y) {
+			return false
+		}
+	}
+	return true
+}
