+	for i := 0; i < len(line)-1; i++ {
+		for j := 0; j < len(polygon); j++ {
+			next := (j + 1) % len(polygon)
+			if lineSegmentsIntersect(line[i], line[i+1], polygon[j], polygon[next]) {
