+			return 0, moerr.NewInvalidInputNoCtx("invalid geometry payload")
+		}
+		count, err := coordinateListPointCount(strings.TrimSpace(ring[1 : len(ring)-1]))
+		if err != nil {
+			return 0, err
+		}
+		total += count
+	}
+	return total, nil
+}
